// DTREE-TREE-QUALITY step 3: common_dtree_build_greedy must reproduce the offline simulator's probability-greedy tree
// (tree_sim.py grow(r, W), raw drafter probs) exactly, on recorded rounds of the ak-dtree-dump-gpu-20261120 capture:
// 27B DFlash2 lattices (predecessor-conditioned scores) and A3B MTP top-k (n-max 4). Fixture: dtree-greedy-rounds.txt,
// generated by the simulator itself (float32-rounded scores). No model needed.

#include "speculative-tree.h"

#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <set>
#include <sstream>
#include <string>
#include <vector>

#define CHECK(cond) do { if (!(cond)) { fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); exit(1); } } while (0)

static std::string key(const std::vector<int32_t> & p) {
    std::string s;
    for (size_t i = 0; i < p.size(); ++i) {
        s += (i ? "." : "") + std::to_string(p[i]);
    }
    return s;
}

int main(int argc, char ** argv) {
    const std::string path = argc > 1 ? argv[1] : "dtree-greedy-rounds.txt";
    std::ifstream in(path);
    if (!in) {
        fprintf(stderr, "cannot open %s\n", path.c_str());
        return 1;
    }

    int kind = 0, D = 0, K = 0;
    std::vector<std::vector<std::vector<float>>> sc; // [j][pred row][k]
    int n_rounds = 0, n_trees = 0, n_bad = 0;
    std::string line;
    while (std::getline(in, line)) {
        std::istringstream ls(line);
        std::string tag;
        ls >> tag;
        if (tag == "R") {
            ls >> kind >> D >> K;
            sc.clear();
            ++n_rounds;
        } else if (tag == "J") {
            int nr = 0;
            ls >> nr;
            std::vector<std::vector<float>> rows(nr, std::vector<float>(K));
            for (auto & r : rows) {
                for (auto & v : r) {
                    std::string t;
                    ls >> t;
                    v = std::strtof(t.c_str(), nullptr);
                }
            }
            sc.push_back(std::move(rows));
        } else if (tag == "W") {
            int W = 0, n = 0;
            ls >> W >> n;
            std::set<std::string> want;
            for (int i = 0; i < n; ++i) {
                std::string t;
                ls >> t;
                want.insert(t);
            }
            CHECK((int) sc.size() == D);
            const common_dtree_scores_fn scores = [&](int32_t j, int32_t pred) {
                const auto & rows = sc[j];
                return rows[(j > 0 && kind == 0) ? pred : 0].data();
            };
            const auto paths = common_dtree_build_greedy(D, K, scores, W, kind == 1);
            std::set<std::string> got;
            for (const auto & p : paths) {
                for (size_t l = 1; l <= p.size(); ++l) {
                    got.insert(key(std::vector<int32_t>(p.begin(), p.begin() + l)));
                }
            }
            // path 0 is the greedy chain prefix: every element is the argmax at its depth
            if (!paths.empty()) {
                int32_t pred = 0;
                for (size_t j = 0; j < paths[0].size(); ++j) {
                    const float * s = scores((int32_t) j, pred);
                    pred = (int32_t) (std::max_element(s, s + K) - s);
                    CHECK(paths[0][j] == pred);
                }
            }
            ++n_trees;
            if (got != want) {
                ++n_bad;
                fprintf(stderr, "MISMATCH round %d kind %d W %d: got %zu nodes, want %zu\n", n_rounds, kind, W, got.size(), want.size());
            }
        }
    }
    printf("test-dtree-greedy: %d rounds, %d trees, %d mismatches\n", n_rounds, n_trees, n_bad);
    CHECK(n_trees > 0);
    CHECK(n_bad == 0);
    printf("OK\n");
    return 0;
}
